# ruff: noqa: E501
from __future__ import annotations

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>zksato Trading Control</title>
<style>
:root{--bg:#080c13;--panel:#101722;--panel2:#151f2d;--line:#263448;--text:#e8eef7;--muted:#8fa0b7;--green:#3ddc97;--red:#ff5c72;--cyan:#43c9ff;--amber:#ffc857}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#122033 0,#080c13 42%);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}.shell{max-width:1700px;margin:auto;padding:20px}.top{display:flex;gap:14px;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;align-items:center;gap:12px}.logo{width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,var(--cyan),#6f7cff);display:grid;place-items:center;color:#06101a;font-weight:900}.brand h1{font-size:20px;margin:0}.sub{color:var(--muted);font-size:12px}.status{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.pill{padding:6px 10px;border:1px solid var(--line);border-radius:999px;background:#0d141e;color:var(--muted)}.pill.good{color:var(--green);border-color:#245b47}.pill.bad{color:var(--red);border-color:#683040}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.card{background:linear-gradient(180deg,rgba(20,29,42,.97),rgba(13,20,30,.97));border:1px solid var(--line);border-radius:15px;padding:14px;box-shadow:0 12px 35px rgba(0,0,0,.2)}.metric{grid-column:span 2;min-height:95px}.metric .v{font-size:23px;font-weight:750;margin-top:8px}.metric .k{color:var(--muted);font-size:12px}.market{grid-column:span 7}.control{grid-column:span 5}.portfolio{grid-column:span 5}.orders{grid-column:span 7}.signals{grid-column:span 4}.alerts{grid-column:span 4}.audit{grid-column:span 4}.chart{grid-column:span 12;height:220px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.head h2{font-size:14px;margin:0}.tablewrap{overflow:auto;max-height:330px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid #1d2939;white-space:nowrap}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.06em}.up{color:var(--green)}.down{color:var(--red)}.muted{color:var(--muted)}button,input,select{border:1px solid var(--line);background:#0b121c;color:var(--text);border-radius:9px;padding:8px 10px}button{cursor:pointer;font-weight:650}button.primary{background:linear-gradient(135deg,#247fff,#39bffc);color:#fff;border:0}button.danger{border-color:#71313c;color:#ff8796}button.good{border-color:#246b50;color:var(--green)}button:disabled{opacity:.45;cursor:not-allowed}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0}.field{display:flex;flex-direction:column;gap:4px;flex:1;min-width:120px}.field label{font-size:11px;color:var(--muted)}.two{display:grid;grid-template-columns:1fr 1fr;gap:8px}.log{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:#b6c4d6}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--muted);margin-right:6px}.dot.run{background:var(--green);box-shadow:0 0 10px var(--green)}.empty{padding:22px;color:var(--muted);text-align:center}canvas{width:100%;height:170px}.notice{font-size:12px;padding:8px 10px;border-radius:8px;background:#101c29;color:#9eb6d1;border:1px solid #23384f}.tabs{display:flex;gap:5px}.tiny{font-size:11px}.right{text-align:right}@media(max-width:1100px){.metric{grid-column:span 4}.market,.control,.portfolio,.orders{grid-column:span 12}.signals,.alerts,.audit{grid-column:span 6}}@media(max-width:700px){.shell{padding:10px}.metric,.signals,.alerts,.audit{grid-column:span 12}.top{align-items:flex-start;flex-direction:column}.two{grid-template-columns:1fr}}
</style>
</head>
<body><div class="shell">
<div class="top"><div class="brand"><div class="logo">ZK</div><div><h1>zksato Trading Control</h1><div class="sub">Risk-first automation · SET / TFEX control plane</div></div></div><div class="status"><span id="mode" class="pill">mode</span><span id="botpill" class="pill"><span id="botdot" class="dot"></span><span id="botstate">stopped</span></span><span id="clock" class="pill"></span></div></div>
<div class="grid">
<div class="card metric"><div class="k">EQUITY</div><div id="equity" class="v">—</div><div id="daily" class="tiny muted">—</div></div>
<div class="card metric"><div class="k">CASH</div><div id="cash" class="v">—</div><div class="tiny muted">available paper cash</div></div>
<div class="card metric"><div class="k">MARKET VALUE</div><div id="marketvalue" class="v">—</div><div id="positionsCount" class="tiny muted">0 positions</div></div>
<div class="card metric"><div class="k">UNREALIZED P/L</div><div id="upnl" class="v">—</div><div class="tiny muted">mark-to-market</div></div>
<div class="card metric"><div class="k">ORDERS</div><div id="orderCount" class="v">0</div><div class="tiny muted">session history</div></div>
<div class="card metric"><div class="k">SIGNALS</div><div id="signalCount" class="v">0</div><div class="tiny muted">automation events</div></div>

<div class="card market"><div class="head"><h2>Market Watch</h2><div class="row"><button id="demoBtn" class="good" onclick="toggleDemo()">Start demo feed</button><button onclick="refresh()">Refresh</button></div></div><div class="tablewrap"><table><thead><tr><th>Symbol</th><th>Last</th><th>Change</th><th>Bid</th><th>Offer</th><th>Volume</th><th>Updated</th></tr></thead><tbody id="marketRows"></tbody></table></div></div>

<div class="card control"><div class="head"><h2>Automation</h2><span class="tiny muted">live autonomous orders are blocked</span></div><div class="notice">Paper and Settrade UAT can be automated. Live mode always requires an explicit confirmed order; the bot cannot bypass that boundary.</div><div class="row"><div class="field"><label>Symbols</label><input id="symbols" value="AOT,PTT,CPALL,KBANK,ADVANC"></div></div><div class="two"><div class="field"><label>Strategy</label><select id="strategy"><option value="ema_cross">EMA Cross</option><option value="rsi_reversion">RSI Reversion</option><option value="breakout">Breakout</option></select></div><div class="field"><label>Order size</label><input id="size" type="number" value="100" min="1"></div><div class="field"><label>Stop loss %</label><input id="sl" type="number" value="2" step="0.1"></div><div class="field"><label>Take profit %</label><input id="tp" type="number" value="4" step="0.1"></div></div><div class="row"><label><input id="auto" type="checkbox" checked> auto execute</label><button class="primary" onclick="startBot()">Start bot</button><button class="danger" onclick="stopBot()">Stop</button><button onclick="tickBot()">Run tick</button></div><div class="head"><h2>Manual Order</h2></div><div class="two"><div class="field"><label>Symbol</label><input id="osymbol" value="AOT"></div><div class="field"><label>Side</label><select id="oside"><option value="buy">Buy</option><option value="sell">Sell</option></select></div><div class="field"><label>Quantity</label><input id="oqty" type="number" value="100"></div><div class="field"><label>Type</label><select id="otype"><option value="market">Market</option><option value="limit">Limit</option></select></div><div class="field"><label>Limit price</label><input id="oprice" type="number" step="0.01" placeholder="required for limit"></div><div class="field"><label>Live confirmation token</label><input id="oconfirm" type="password" placeholder="only used in live mode"></div></div><div class="row"><button class="primary" onclick="manualOrder()">Submit order</button><span id="orderMsg" class="tiny muted"></span></div></div>

<div class="card portfolio"><div class="head"><h2>Portfolio</h2></div><div class="tablewrap"><table><thead><tr><th>Symbol</th><th>Qty</th><th>Avg</th><th>Last</th><th>Value</th><th>P/L</th></tr></thead><tbody id="portfolioRows"></tbody></table></div></div>
<div class="card orders"><div class="head"><h2>Orders</h2></div><div class="tablewrap"><table><thead><tr><th>Time</th><th>Symbol</th><th>Side</th><th>Qty</th><th>Fill</th><th>Price</th><th>Status</th><th>Source</th></tr></thead><tbody id="orderRows"></tbody></table></div></div>

<div class="card chart"><div class="head"><h2>Equity Monitor</h2><span class="tiny muted">browser session samples</span></div><canvas id="chart" width="1400" height="170"></canvas></div>

<div class="card signals"><div class="head"><h2>Signals</h2></div><div id="signals" class="tablewrap"></div></div>
<div class="card alerts"><div class="head"><h2>Price Alerts</h2></div><div class="row"><input id="asymbol" value="AOT" style="width:80px"><select id="aop"><option value="gte">≥</option><option value="lte">≤</option></select><input id="aprice" type="number" step="0.01" placeholder="price" style="width:100px"><button onclick="addAlert()">Add</button></div><div id="alerts"></div></div>
<div class="card audit"><div class="head"><h2>Audit Trail</h2></div><div id="audit" class="tablewrap log"></div></div>
</div></div>
<script>
const money=n=>new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB',maximumFractionDigits:2}).format(Number(n||0));const num=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(Number(n||0));let snapshot=null,demo=false,equityHistory=[];
async function api(path,opt){const r=await fetch(path,opt);let body=null;try{body=await r.json()}catch{}if(!r.ok)throw new Error(body?.detail?JSON.stringify(body.detail):`HTTP ${r.status}`);return body}
function cls(n){return Number(n)>=0?'up':'down'}function time(s){return s?new Date(s).toLocaleTimeString():''}
async function refresh(){try{snapshot=await api('/v1/dashboard');render(snapshot)}catch(e){console.error(e)}}
function render(s){document.getElementById('mode').textContent=`${s.mode.toUpperCase()} · ${s.kill_switch?'KILL SWITCH':'risk active'}`;document.getElementById('mode').className='pill '+(s.kill_switch?'bad':'good');document.getElementById('botstate').textContent=s.bot.state;document.getElementById('botdot').className='dot '+(s.bot.state==='running'?'run':'');document.getElementById('equity').textContent=money(s.portfolio.equity);document.getElementById('cash').textContent=money(s.portfolio.cash);document.getElementById('marketvalue').textContent=money(s.portfolio.market_value);document.getElementById('upnl').textContent=money(s.portfolio.unrealized_pnl);document.getElementById('upnl').className='v '+cls(s.portfolio.unrealized_pnl);document.getElementById('daily').textContent=`Daily P/L ${money(s.portfolio.daily_pnl)}`;document.getElementById('daily').className='tiny '+cls(s.portfolio.daily_pnl);document.getElementById('positionsCount').textContent=`${s.portfolio.positions.length} positions`;document.getElementById('orderCount').textContent=s.orders.length;document.getElementById('signalCount').textContent=s.signals.length;renderMarket(s.quotes);renderPortfolio(s.portfolio.positions);renderOrders(s.orders);renderSignals(s.signals);renderAlerts(s.alerts);renderAudit(s.audit);equityHistory.push(Number(s.portfolio.equity||0));if(equityHistory.length>180)equityHistory.shift();drawChart()}
function renderMarket(rows){const el=document.getElementById('marketRows');el.innerHTML=rows.length?rows.map(q=>`<tr><td><b>${q.symbol}</b></td><td>${num(q.last)}</td><td class="${cls(((q.last-(q.previous_close||q.last))/(q.previous_close||q.last))*100)}">${num(((q.last-(q.previous_close||q.last))/(q.previous_close||q.last))*100)}%</td><td>${num(q.bid)}</td><td>${num(q.offer)}</td><td>${num(q.volume)}</td><td class="muted">${time(q.timestamp)}</td></tr>`).join(''):`<tr><td colspan="7" class="empty">No quotes yet — start demo feed or POST /v1/market/quote</td></tr>`}
function renderPortfolio(rows){document.getElementById('portfolioRows').innerHTML=rows.length?rows.map(p=>`<tr><td><b>${p.symbol}</b></td><td>${p.quantity}</td><td>${num(p.average_price)}</td><td>${num(p.market_price)}</td><td>${money(p.market_value)}</td><td class="${cls(p.unrealized_pnl)}">${money(p.unrealized_pnl)} (${num(p.unrealized_pnl_pct)}%)</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No positions</td></tr>`}
function renderOrders(rows){document.getElementById('orderRows').innerHTML=rows.slice(0,80).map(o=>`<tr><td>${time(o.created_at)}</td><td><b>${o.symbol}</b></td><td class="${o.side==='buy'?'up':'down'}">${o.side.toUpperCase()}</td><td>${o.quantity}</td><td>${o.filled_quantity}</td><td>${num(o.average_fill_price||o.price)}</td><td>${o.status}</td><td class="muted">${o.source}</td></tr>`).join('')||`<tr><td colspan="8" class="empty">No orders</td></tr>`}
function renderSignals(rows){document.getElementById('signals').innerHTML=rows.slice(0,30).map(x=>`<div style="padding:9px;border-bottom:1px solid #1d2939"><b class="${x.action==='buy'?'up':'down'}">${x.action.toUpperCase()}</b> ${x.symbol} <span class="muted">${x.strategy}</span><div class="tiny muted">${x.reason} · ${time(x.timestamp)}</div></div>`).join('')||'<div class="empty">No signals</div>'}
function renderAlerts(rows){document.getElementById('alerts').innerHTML=rows.map(a=>`<div class="row"><span>${a.symbol} ${a.operator==='gte'?'≥':'≤'} ${num(a.price)}</span><span class="pill tiny">${a.enabled?'armed':'triggered'}</span><button onclick="deleteAlert('${a.id}')">×</button></div>`).join('')||'<div class="empty">No alerts</div>'}
function renderAudit(rows){document.getElementById('audit').innerHTML=rows.slice(0,60).map(a=>`<div style="padding:7px 0;border-bottom:1px solid #1d2939"><span class="muted">${time(a.timestamp)}</span> ${a.event_type}<br>${a.message}</div>`).join('')||'<div class="empty">No audit events</div>'}
function drawChart(){const c=document.getElementById('chart'),x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);x.strokeStyle='#263448';x.lineWidth=1;for(let i=1;i<5;i++){x.beginPath();x.moveTo(0,h*i/5);x.lineTo(w,h*i/5);x.stroke()}if(equityHistory.length<2)return;const min=Math.min(...equityHistory),max=Math.max(...equityHistory),span=Math.max(max-min,1);x.strokeStyle='#43c9ff';x.lineWidth=3;x.beginPath();equityHistory.forEach((v,i)=>{const px=i/(equityHistory.length-1)*w,py=h-10-(v-min)/span*(h-20);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}
async function startBot(){try{const symbols=document.getElementById('symbols').value.split(',').map(s=>s.trim()).filter(Boolean);await api('/v1/bot/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbols,strategy:{name:document.getElementById('strategy').value},order_size:Number(document.getElementById('size').value),stop_loss_pct:Number(document.getElementById('sl').value),take_profit_pct:Number(document.getElementById('tp').value),auto_execute:document.getElementById('auto').checked,cooldown_seconds:30})});refresh()}catch(e){alert(e.message)}}
async function stopBot(){await api('/v1/bot/stop',{method:'POST'});refresh()}async function tickBot(){await api('/v1/bot/tick',{method:'POST'});refresh()}
async function toggleDemo(){if(!demo){await api('/v1/market/demo/start',{method:'POST'});demo=true}else{await api('/v1/market/demo/stop',{method:'POST'});demo=false}document.getElementById('demoBtn').textContent=demo?'Stop demo feed':'Start demo feed'}
async function manualOrder(){const msg=document.getElementById('orderMsg');try{const type=document.getElementById('otype').value,price=document.getElementById('oprice').value;const symbol=document.getElementById('osymbol').value.toUpperCase();const quote=snapshot?.quotes.find(q=>q.symbol===symbol);const p=type==='limit'?Number(price):null;const reference=quote?.last||p;const side=document.getElementById('oside').value;const payload={intent:{symbol,side,quantity:Number(document.getElementById('oqty').value),order_type:type,price:p,stop_loss:side==='buy'&&reference?reference*.98:null,take_profit:side==='buy'&&reference?reference*1.04:null,source:'dashboard'},risk:{reference_price:reference,line_available:snapshot?.portfolio.cash,portfolio_value:snapshot?.portfolio.equity,current_positions:snapshot?.portfolio.positions.length||0,orders_today:snapshot?.orders.length||0,position_pct_after_trade:reference&&snapshot?.portfolio.equity?Math.min(100,reference*Number(document.getElementById('oqty').value)/snapshot.portfolio.equity*100):0},confirmation_token:document.getElementById('oconfirm').value||null};const o=await api('/v1/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});msg.textContent=`${o.status}: ${o.symbol} ${o.side}`;refresh()}catch(e){msg.textContent=e.message}}
async function addAlert(){await api('/v1/alerts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol:document.getElementById('asymbol').value,operator:document.getElementById('aop').value,price:Number(document.getElementById('aprice').value)})});refresh()}async function deleteAlert(id){await api(`/v1/alerts/${id}`,{method:'DELETE'});refresh()}
setInterval(()=>document.getElementById('clock').textContent=new Date().toLocaleString(),1000);setInterval(refresh,2000);refresh();
</script></body></html>'''
